const inter = "";
const interBold = "";
const display = "";
const mono = "";
const serif = "";
const serifBold = "";
const openSans = "";
const openSansBold = "";
const liberation = "";
const liberationBold = "";
const bytes = (base64: string) => new Uint8Array(Buffer.from(base64, "base64"));
export function billingDocumentFonts(config?: InvoiceTemplate): FontRegistration[] {
 const brandSerif = !config?.brand || config.brand.font === "serif";
 return [
  { family: "Invoice", src: bytes(brandSerif ? serif : inter) }, { family: "Invoice", src: bytes(brandSerif ? serifBold : interBold), fontWeight: "bold" },
  { family: "InvoiceSans", src: bytes(inter) }, { family: "InvoiceSans", src: bytes(interBold), fontWeight: "bold" },
  { family: "InvoiceSerif", src: bytes(serif) }, { family: "InvoiceSerif", src: bytes(serifBold), fontWeight: "bold" },
  { family: "InvoiceMono", src: bytes(mono) }, { family: "InvoiceMono", src: bytes(mono), fontWeight: "bold" },
  { family: "InvoiceOpenSans", src: bytes(openSans) }, { family: "InvoiceOpenSans", src: bytes(openSansBold), fontWeight: "bold" },
  { family: "InvoiceLiberationSerif", src: bytes(liberation) }, { family: "InvoiceLiberationSerif", src: bytes(liberationBold), fontWeight: "bold" },
  { family: "InvoiceDisplay", src: bytes(display) }, { family: "InvoiceLabel", src: bytes(mono) },
 ];
}
